    "author": "司马吹风",
    "description": "吕端回到政事堂，总觉得官家这等境况，升遐在须臾之间，正考虑要先着手布置一些官家身后事。 王继恩火急火燎赶到了，吕端还未来得及问，王继恩已放出悲声来：“相公，大事不好，官家晏驾，皇后请你入宫商议官家身后事！” 吕端急促问：“派人去请太子了么？” “我不知晓！” 吕端听皇后着急召自家入宫，却未想到传太子赵恒入宫，不禁一怔。 吕端慎重地问王继恩：“皇后怎地没有请太子入宫？” 王继恩没想到吕端有此一问，他一向狡诈，此刻心怀鬼胎，也不免有些支吾道…",
    "content": "吕端回到政事堂，总觉得官家这等境况，升遐在须臾之间，正考虑要先着手布置一些官家身后事。 王继恩火急火燎赶到了，吕端还未来得及问，王继恩已放出悲声来：“相公，大事不好，官家晏驾，皇后请你入宫商议官家身后事！” 吕端急促问：“派人去请太子了么？” “我不知晓！” 吕端听皇后着急召自家入宫，却未想到传太子赵恒入宫，不禁一怔。 吕端慎重地问王继恩：“皇后怎地没有请太子入宫？” 王继恩没想到吕端有此一问，他一向狡诈，此刻心怀鬼胎，也不免有些支吾道：“相公…相公进宫后便明白了！” 吕端稳重道：“官家大行，太子需在灵柩前依遗诏即…"
