    "description": "36氪获悉，10月1日收盘，美股三大指数集体上涨，纳指涨0.04%，道指涨0.04%，标普500指数涨0.19%；大型科技股多数下跌，奈飞跌超2%，谷歌跌超1%，苹果、亚马逊、特斯拉、英特尔、微软小幅下跌；SK海力士涨超5%，闪迪涨超2%，英伟达涨超1%。热门中概股普跌，老虎证券跌超6%，理想汽车、腾讯音乐跌超2%，拼多多、名创优品、微博，百度、小鹏集团跌超1%。",
    "content": "36氪获悉，10月1日收盘，美股三大指数集体上涨，纳指涨0.04%，道指涨0.04%，标普500指数涨0.19%；大型科技股多数下跌，奈飞跌超2%，谷歌跌超1%，苹果、亚马逊、特斯拉、英特尔、微软小幅下跌；SK海力士涨超5%，闪迪涨超2%，英伟达涨超1%。热门中概股普跌，老虎证券跌超6%，理想汽车、腾讯音乐跌超2%，拼多多、名创优品、微博，百度、小鹏集团跌超1%。"
