    "content": "来源 |&nbsp;FoST未来叙事 文&nbsp;| 葱葱 82亿美元，芯片巨头AMD以全股票形式收购世界模型公司World Labs。 AMD在收购公告里写道：“World Labs 的模型经验，将帮助AMD更深入地理解工作负载如何演变，进而塑造未来的技术路线图。” 换句话说，AMD看中的，不只是World Labs今天的模型能力，更是世界模型这类前沿模型可能给芯片硬件研发带来的“前瞻性”。 AMD董事长兼CEO苏姿丰（左）和World Labs联创李飞飞（右） 2026年以来，世界模型正替代大语言模型成为AI…"
