    "description": "2026年10月02日 金秋时节山河锦绣，中华儿女喜迎国庆。在庆祝中华人民共和国成立77周年招待会上，习近平总书记指出：“此时此刻，我们为新中国取得的举世瞩目成就无比自豪，对中国式现代化的光明前景充满信心。” 神州大地上，到处洋溢着浓郁热烈、欢欣鼓舞的节日氛围。 祝福伟大祖国，激扬奋斗豪情。从天安门广场，到山乡和边陲，再到海外的亚运会赛场，鲜艳的国旗、激昂的国歌让我们心潮澎湃、充满力量，一张张自信的笑脸，一句句深情的祝福，汇聚成奋进新征…",
    "content": "2026年10月02日 金秋时节山河锦绣，中华儿女喜迎国庆。在庆祝中华人民共和国成立77周年招待会上，习近平总书记指出：“此时此刻，我们为新中国取得的举世瞩目成就无比自豪，对中国式现代化的光明前景充满信心。” 神州大地上，到处洋溢着浓郁热烈、欢欣鼓舞的节日氛围。 祝福伟大祖国，激扬奋斗豪情。从天安门广场，到山乡和边陲，再到海外的亚运会赛场，鲜艳的国旗、激昂的国歌让我们心潮澎湃、充满力量，一张张自信的笑脸，一句句深情的祝福，汇聚成奋进新征程、建功新时代的磅礴伟力。 欢度国庆佳节，焕发文旅活力。人们或奔赴山川名胜，感受…"
