    "description": "2026年10月02日 XMAGE 升级为“华为睿影XMAGE”，开启华为移动影像新十年 2026年10月1日，在HUAWEI Mate 90系列及全场景新品发布会上，华为正式宣布移动影像品牌XMAGE升级为“华为睿影XMAGE”。在技术底座上，逻辑折叠τ芯片为影像计算提供新的算力支撑，进一步完善“软硬芯云”协同的全栈技术体系；在影像能力上，移动影像“新物种”—全新华为睿影Z10模块相机面市，再次突破手机的光学边界，HUAWEI Mat…",
    "content": "2026年10月02日 XMAGE 升级为“华为睿影XMAGE”，开启华为移动影像新十年 2026年10月1日，在HUAWEI Mate 90系列及全场景新品发布会上，华为正式宣布移动影像品牌XMAGE升级为“华为睿影XMAGE”。在技术底座上，逻辑折叠τ芯片为影像计算提供新的算力支撑，进一步完善“软硬芯云”协同的全栈技术体系；在影像能力上，移动影像“新物种”—全新华为睿影Z10模块相机面市，再次突破手机的光学边界，HUAWEI Mate 90系列“睿影红枫人像”功能，新增人像原片、柔光人像、绚丽烟花、星芒效果，人…"
