    "pub_date": "2026-10-02 08:26:02",
    "author": "",
    "description": "2026年10月02日 又逢国庆。新中国七十七载砥砺前行，山河日新，发展成果惠及万家。这久久为功的现代化实践背后，离不开一轮轮接力推进的五年规划（计划）。 李捷新作《规划中国：五年规划与中国共产党》，就带我们读懂70余年家国蝶变的内在逻辑，探寻中国式现代化的制度密码。作者把这段波澜壮阔的历程概括为工业立国、改革富国、创新强国，这不是抽象的理论叙事，而是一代代人脚踏实地、接续奋斗走出的道路。所谓规划中国，就是以长远眼光谋定发展蓝图，把每一…",
    "content": "2026年10月02日 《规划中国：五年规划与中国共产党》：李捷著；浙江教育出版社出版。 \"> 又逢国庆。新中国七十七载砥砺前行，山河日新，发展成果惠及万家。这久久为功的现代化实践背后，离不开一轮轮接力推进的五年规划（计划）。 李捷新作《规划中国：五年规划与中国共产党》，就带我们读懂70余年家国蝶变的内在逻辑，探寻中国式现代化的制度密码。作者把这段波澜壮阔的历程概括为工业立国、改革富国、创新强国，这不是抽象的理论叙事，而是一代代人脚踏实地、接续奋斗走出的道路。所谓规划中国，就是以长远眼光谋定发展蓝图，把每一轮五年规…"
