    "author": "",
    "description": "2026年10月02日 要说《走进阿嬷的潮汕》一书的出版跟电影《给阿嬷的情书》毫无关系，那是说不过去的；但若认定此乃跟风之作，则又大谬不然。此前好几年，广东教育出版社一直跟我们三位主编商议，如何将总共四册的《潮汕文化读本》改造成面向全国的大众读物。这套2017年初刊、日后多次重印的乡土教材，在潮汕地区声誉甚佳，在东南亚华侨中也有一定的知名度。若改弦易辙，须大动干戈。或删繁就简，或拾遗补缺，或拓展视野，或深化内涵，那样才可能兼及雅俗，呈现…",
