    "pub_date": "2026-10-02 07:43:42",
    "author": "",
    "description": "家是最小国，国是千万家。修齐治平、兴亡有责的家国情怀是中华优秀传统文化的重要元素。习近平总书记始终高度重视家国情怀的传承和弘扬，在多个场合深刻阐述“家”“国”关系。一起重温这些深情话语，感悟总书记心中的“家”与“国”。 策划：石锋 吴丹 统筹：黄庆华 王浩程 文案：周顺龙 设计：潘红宇 新华社新媒体中心制作 新华社出品",
    "content": "家是最小国，国是千万家。修齐治平、兴亡有责的家国情怀是中华优秀传统文化的重要元素。习近平总书记始终高度重视家国情怀的传承和弘扬，在多个场合深刻阐述“家”“国”关系。一起重温这些深情话语，感悟总书记心中的“家”与“国”。 策划：石锋 吴丹 统筹：黄庆华 王浩程 文案：周顺龙 设计：潘红宇 新华社新媒体中心制作 新华社出品"
