    "description": "9月29日，2026-2027赛季中国男子篮球职业联赛（以下简称“CBA联赛”）工作会议在北京召开。国家体育总局副局长、党组成员、CBA联赛组委会主任张家胜参会并讲话。中国篮球协会领导班子及各相关部门负责人，20家CBA俱乐部相关负责人、球队主教练和赛区相关负责人参加会议。 爬坡过坎，不进则退 张家胜指出，CBA联赛是中国篮球改革发展的龙头和旗帜，必须从“国之大者”的高度认识和把握职业联赛的地位作用。同时必须清醒地看到，中国篮球正处在爬…",
    "content": "9月29日，2026-2027赛季中国男子篮球职业联赛（以下简称“CBA联赛”）工作会议在北京召开。国家体育总局副局长、党组成员、CBA联赛组委会主任张家胜参会并讲话。中国篮球协会领导班子及各相关部门负责人，20家CBA俱乐部相关负责人、球队主教练和赛区相关负责人参加会议。 爬坡过坎，不进则退 张家胜指出， CBA联赛是中国篮球改革发展的龙头和旗帜，必须从“国之大者”的高度认识和把握职业联赛的地位作用。同时必须清醒地看到，中国篮球正处在爬坡过坎、不进则退的关键阶段，国家队成绩与群众期待还有明显差距，赛风赛纪问题尚未…"
