    "content": "首先这不是 AI vibe 的创作。是真的古法编程，走了很多弯路，很多债现在都在还。现在有了 AI ，希望以后会轻松些，并且逐渐提高服务质量，不再受限我个人的能力。 历史：不是我要重复造轮子，是现有的轮子太糟： 疫情刚结束时，时隔 7 年终于回老家一次。发现以前只有部分本地人玩的掼蛋火了，家乡淮安处处是掼蛋，我妈迷的不行。但是我妈不喜欢用手机玩，不仅是我妈，小区大爷大妈都一样。我研究了一下为什么： 现有的游戏不注重掼蛋体验，注重捞金。 打开应用先来各种活动，老人打开应用不知道该干嘛。 有的 bug 满天飞，收费项目…"
