    "description": "我们家现在小区，阳台外面是没有那种晾衣杆的，物业原则上不让装，但是小区也有些年份了，外立面管理没有那么严，有几家装了。 我以前的房子是有那种晾衣杆的，然后现在就挂在阳台里面的晾衣架上，每天接触阳光时间少了，虽然日常还是可以干的，但是吧，隔着玻璃和纱窗，家里也装了烘干机，但是总感觉少了些什么。 我考虑装一个的，有点纠结，因为现在封阳台的立柱是圆形的（小区的统一设计风格），网购了一个，回来研究了一下安装固定方式，怕不稳定。 但是现在新房，尤…",
    "content": "我们家现在小区，阳台外面是没有那种晾衣杆的，物业原则上不让装，但是小区也有些年份了，外立面管理没有那么严，有几家装了。 我以前的房子是有那种晾衣杆的，然后现在就挂在阳台里面的晾衣架上，每天接触阳光时间少了，虽然日常还是可以干的，但是吧，隔着玻璃和纱窗，家里也装了烘干机，但是总感觉少了些什么。 我考虑装一个的，有点纠结，因为现在封阳台的立柱是圆形的（小区的统一设计风格），网购了一个，回来研究了一下安装固定方式，怕不稳定。 但是现在新房，尤其是那种科技房，基本上都是不允许室外晾晒的吧，冬天晒棉被怎么操的呢？统一到楼顶？…"
