    "content": "新华社纽约10月1日电 纽约股市三大股指1日上涨。 截至当天收盘，道琼斯工业平均指数比前一交易日上涨20.51点，收于50926.56点，涨幅为0.04%；标准普尔500种股票指数上涨14.91点，收于7666.45点，涨幅为0.19%；纳斯达克综合指数上涨10.53点，收于26871.60点，涨幅为0.04%。 板块方面，标普500指数十一大板块六跌五涨。医疗板块和通信服务板块分别以1.30%和1.19%的跌幅领跌，能源板块和工业板块分别以1.92%和1.00%的涨幅领涨。"
