    "content": "01/10/2026 - 21:20 美国前联准会（Fed）高级官员罗杰斯（John Harold Rogers）涉嫌多年向中国情报人员提供联准会资料，并在接受调查时否认曾外泄受限资讯，最终被陪审团判定虚假陈述罪成立。不过，陪审团未认定他共谋从事经济间谍活动。罗杰斯今年7月被判处38个月联邦监禁。 这起案件牵涉网路恋情、婚姻、金钱往来、裸照勒索及中国情报活动。美国检方在审判时形容，案件“就像一部间谍小说”。 联邦检察官尼古拉斯・亨特（Nicholas Hunter）告诉陪审团：“有性、有金钱、有操纵、有与中国可疑人…"
