    "content": "新华社马德里10月1日电（记者孟鼎博 宁雨轩）西班牙首都马德里乌塞拉区一座融合中西文化元素的牌坊1日正式揭幕。牌坊上，两条中国龙与象征马德里的熊“相遇”，为街区增添一座文化新地标。 中国驻西班牙大使姚敬、马德里市长阿尔梅达、西班牙艺术家奥田等出席揭幕仪式，众多华侨华人和当地居民共同见证。 这座牌坊由乌塞拉区政府、当地华人社区和奥田共同合作打造。主体采用中式传统牌坊形式，饰有云纹，两面分别题有“天下为公”和“和为贵”，立柱上书有“圆融通中西，慈敬聚友邻”等文字。牌坊上龙与熊的塑像采用奥田标志性的几何结构和鲜艳色块，与…"
