    "description": "新华社明斯克10月1日电（记者陈汀）白俄罗斯第一副总理斯诺普科夫1日接受白俄罗斯国家通讯社采访时说，“信任”一词成为2026年白俄罗斯和中国关系的关键词，两国持续将全天候全面战略伙伴关系转化为涵盖工业、投资、贸易、数字经济、地区等层面务实互利的项目。 斯诺普科夫指出，白俄罗斯和中国高度互信，这种信任靠的是岁月沉淀、实际行动以及彼此真诚相待。从两国元首会晤到高层访问，从产业与投资合作论坛到地方合作论坛，当前白中贸易和联合项目发展呈现积极态…",
    "content": "新华社明斯克10月1日电（记者陈汀）白俄罗斯第一副总理斯诺普科夫1日接受白俄罗斯国家通讯社采访时说，“信任”一词成为2026年白俄罗斯和中国关系的关键词，两国持续将全天候全面战略伙伴关系转化为涵盖工业、投资、贸易、数字经济、地区等层面务实互利的项目。 斯诺普科夫指出，白俄罗斯和中国高度互信，这种信任靠的是岁月沉淀、实际行动以及彼此真诚相待。从两国元首会晤到高层访问，从产业与投资合作论坛到地方合作论坛，当前白中贸易和联合项目发展呈现积极态势，且这一态势有望成倍增长。 斯诺普科夫表示，近年来，自中国来白俄罗斯的游客流量…"
