    "content": "新华社亚的斯亚贝巴10月1日电（记者刘方强）埃塞俄比亚外交部1日发布声明，宣布关闭其在厄立特里亚首都阿斯马拉的大使馆，并将10名厄立特里亚驻埃塞外交官列为“不受欢迎的人”，要求其在48小时内离境。 埃塞外交部表示，这是“针对厄立特里亚对埃塞俄比亚所采取的直接和间接的敌对及挑衅行为”所作出的决定。 埃塞外交部称，这10名厄立特里亚外交官违反《维也纳外交关系公约》，参与对埃塞国家安全构成直接威胁的活动，因而被列为“不受欢迎的人”。 埃塞政府进一步敦促厄立特里亚政府“停止一切违反主权国家间关系原则的行为”。 近期，“提格…"
