    "description": "新华社武汉10月1日电（记者王自宸）国庆假期首日，铁路迎来客流高峰，中国铁路武汉局集团有限公司发送旅客125.6万人次，其中汉口站单日发送旅客27.1万人次、同比增长10.5%。 10月1日，武铁旅游、探亲、学生客流交织叠加，长途直通客流集中在北京、上海、广州、深圳、成都、重庆等地；湖北省内短途客流集中在汉十、郑渝、汉宜等线路集群。 为满足旅客出行需求，武铁在实行高峰列车运行图的基础上，加开始发旅客列车379列。其中，至京津冀、长三角、…",
    "content": "新华社武汉10月1日电（记者王自宸）国庆假期首日，铁路迎来客流高峰，中国铁路武汉局集团有限公司发送旅客125.6万人次，其中汉口站单日发送旅客27.1万人次、同比增长10.5%。 10月1日，武铁旅游、探亲、学生客流交织叠加，长途直通客流集中在北京、上海、广州、深圳、成都、重庆等地；湖北省内短途客流集中在汉十、郑渝、汉宜等线路集群。 为满足旅客出行需求，武铁在实行高峰列车运行图的基础上，加开始发旅客列车379列。其中，至京津冀、长三角、珠三角、成渝等方向始发旅客列车72列；武汉往返十堰、宜昌、襄阳、麻城等地旅客列车…"
