    "content": "新华社洛杉矶10月1日电 美国太空探索技术公司的“龙”飞船10月1日搭载4名宇航员升空，开启前往国际空间站的载人飞行任务。 “龙”飞船于美国东部时间1日11时10分许（北京时间1日23时10分许）搭乘“猎鹰9”号火箭从佛罗里达州卡纳维拉尔角太空军基地发射升空。随后，飞船与火箭分离，继续飞往国际空间站。按计划，“龙”飞船将飞行约8小时后与国际空间站对接。 此次任务代号为“载人13号”，是载人“龙”飞船第13次执行为国际空间站运送轮换宇航员的任务。飞船上的4名宇航员分别是美国航空航天局宇航员杰茜卡·沃特金斯和卢克·德莱…"
